    def __hash__(self): return hash(self.val)

class Float(Value):
    def __init__(self, val): self.val = val
    def __repr__(self):
        if self.val == int(self.val):
            return f"{float(self.val):.1f}"
        return str(self.val)
    def __eq__(self, other): return isinstance(other, Float) and self.val == other.val
    def __hash__(self): return hash(self.val)

class Char(Value):
