    def __init__(self, fn): self.fn = fn
    def __repr__(self): return "function"

# Lexer
class Token:
    def __init__(self, type, value, line, col):
        self.type = type
        self.value = value
        self.line = line
        self.col = col
    def __repr__(self): return f"{self.type}({self.value}) at {self.line}:{self.col}"

class Lexer:
    def __init__(self, text, filename):
        self.text = text
        self.filename = filename
        self.pos = 0
        self.line = 1
        self.col = 0
        self.tokens = []
        self.keywords = {
            'let', 'function', 'return', 'if', 'then', 'else', 'end', 'while', 'do', 'for', 'in', 'and', 'or', 'not', 'nil', 'true', 'false', 'break'
        }

    def error(self, msg, line=None, col=None):
        l = line or self.line
        c = col or self.col
        print(f"Error: {self.filename} (line {l}, column {c}) - {msg}")
        sys.exit(2)

    def lex(self):
        while self.pos < len(self.text):
            c = self.text[self.pos]
