                elif self.pos < len(self.text) and self.text[self.pos] in 'eE':
                    self.pos += 1
                    self.col += 1
                    if self.pos < len(self.text) and self.text[self.pos] in '+-':
                        self.pos += 1
                        self.col += 1
                    while self.pos < len(self.text) and self.text[self.pos].isdigit():
                        self.pos += 1
                        self.col += 1
                    # Scientific notation for integers should still be floats?
                    # Hush lexer seems to expand them to ints in --lex output if they are integers
                    val = self.text[start_pos:self.pos]
