                        self.pos += 1
                        self.col += 1
                        esc = self.text[self.pos]
                        if esc == 'n': val += '\n'
                        elif esc == 't': val += '\t'
                        elif esc == '"': val += '"'
                        elif esc == '\\': val += '\\'
                        elif esc == '0': val += '\0'
