        if type == 'binop':
            op = expr[1]
            left = self.eval_expr(expr[2], env)
            right = self.eval_expr(expr[3], env)
            if op == '+': return Int(left.val + right.val)
            if op == '-': return Int(left.val - right.val)
            if op == '*': return Int(left.val * right.val)
            if op == '/': return Int(left.val // right.val)
            if op == '%': return Int(left.val % right.val)
            if op == '++': return String(left.val + right.val)
            if op == '==': return Bool(left == right)
            if op == '!=': return Bool(not (left == right))
            if op == '<': return Bool(left.val < right.val)
            if op == '>': return Bool(left.val > right.val)
            if op == '<=': return Bool(left.val <= right.val)
            if op == '>=': return Bool(left.val >= right.val)
            if op == 'and': return Bool(left.val and right.val)
            if op == 'or': return Bool(left.val or right.val)
        if type == 'unary':
            op = expr[1]
            right = self.eval_expr(expr[2], env)
            if op == '-': return Int(-right.val)
            if op == 'not': return Bool(not right.val)
