        if isinstance(func, Function):
            sub_env = Environment(func.env)
            if obj is not None:
                sub_env.set("self", obj)
            for i, p in enumerate(func.params):
                sub_env.set(p, args[i] if i < len(args) else Nil())
            try:
                val = Nil()
                for s in func.body: val = self.eval_stmt(s, sub_env)
