                process = self.exec_command(cmd, env, capture=True)
                out, err = process.communicate()
                stdout += out.decode()
                stderr += err.decode()
                status = process.returncode
                if status != 0: break
            if status == 0:
                return Dict({String("stdout"): String(stdout), String("stderr"): String(stderr)})
            else:
                return Error("command returned non-zero", Dict({
                    String("stdout"): String(stdout),
                    String("stderr"): String(stderr),
                    String("error"): Dict({String("status"): Int(status), String("pos"): String(f"{self.filename} (line ?, column ?)")})
                }))
        elif type_str == '{':
            status = 0
            for cmd in cmds:
                process = self.exec_command(cmd, env, capture=False)
                process.wait()
                status = process.returncode
                if status != 0: break
            if status == 0: return Nil()
            else: return Error("command returned non-zero", Dict({
                String("status"): Int(status),
                String("pos"): String(f"{self.filename} (line ?, column ?)")
            }))
        elif type_str == '&{':
