        if cmd[0] == 'command':
            args = []
            for part in cmd[1]:
                if part[0] == 'arg':
                    arg_val = part[1]
                    if arg_val[0] == 'literal_arg': args.append(arg_val[1])
                    elif arg_val[0] == 'dollar_id':
                        val = env.get(arg_val[1])
                        if val: args.append(str(val))
            return subprocess.Popen(args, stdout=subprocess.PIPE if capture else None, stderr=subprocess.PIPE if capture else None)
        return None

