#!/usr/bin/env python3
import sys
import os
import re
import json
import subprocess
import glob as glob_module

class HushError(Exception):
    def __init__(self, description, payload):
        self.description = description
        self.payload = payload

class HushPanic(Exception):
    def __init__(self, message, pos=None):
        self.message = message
        self.pos = pos
    def __str__(self):
        if self.pos:
            return f"Panic in {self.pos}: {self.message}"
        return f"Panic: {self.message}"

class Value:
    pass

class Nil(Value):
    def __repr__(self): return "nil"
    def __eq__(self, other): return isinstance(other, Nil)
    def __hash__(self): return hash(None)
    def __bool__(self): return False

class Bool(Value):
    def __init__(self, val): self.val = val
    def __repr__(self): return "true" if self.val else "false"
    def __eq__(self, other): return isinstance(other, Bool) and self.val == other.val
    def __hash__(self): return hash(self.val)
    def __bool__(self): return self.val

class Int(Value):
    def __init__(self, val): self.val = val
    def __repr__(self): return str(self.val)
    def __eq__(self, other): return isinstance(other, Int) and self.val == other.val
    def __hash__(self): return hash(self.val)

class Float(Value):
    def __init__(self, val): self.val = val
    def __repr__(self):
        if self.val == int(self.val):
            return f"{float(self.val):.1f}"
        return str(self.val)
    def __eq__(self, other): return isinstance(other, Float) and self.val == other.val
    def __hash__(self): return hash(self.val)

class Char(Value):
    def __init__(self, val): self.val = val
    def __repr__(self): return self.val
    def __eq__(self, other): return isinstance(other, Char) and self.val == other.val
    def __hash__(self): return hash(self.val)

class String(Value):
    def __init__(self, val): self.val = val
    def __repr__(self): return f'"{self.escape(self.val)}"'
    def escape(self, s):
        return s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n').replace('\t', '\\t').replace('\0', '\0')
    def __eq__(self, other): return isinstance(other, String) and self.val == other.val
    def __hash__(self): return hash(self.val)

class Array(Value):
    def __init__(self, val): self.val = val
    def __repr__(self):
        return "[ " + ", ".join(repr(v) for v in self.val) + " ]" if self.val else "[]"
    def __eq__(self, other): return self is other

class Dict(Value):
    def __init__(self, val=None):
        self.val = val or {} # Value -> Value
    def __repr__(self):
        if not self.val: return "@[]"
        items = []
        for k, v in self.val.items():
            k_repr = f'"{k.val}"' if isinstance(k, String) else repr(k)
            items.append((k_repr, repr(v)))
        items.sort()
        return "@[ " + ", ".join(f"{k}: {v}" for k, v in items) + " ]"
    def __eq__(self, other): return self is other

class Error(Value):
    def __init__(self, description, payload):
        self.description = description
        self.payload = payload
    def __repr__(self):
        return f'error: "{self.description}" ({repr(self.payload)})'
    def __eq__(self, other): return self is other

class Function(Value):
    def __init__(self, name, params, body, env):
        self.name = name
        self.params = params
        self.body = body
        self.env = env
    def __repr__(self): return "function"

class NativeFunction(Value):
    def __init__(self, fn): self.fn = fn
    def __repr__(self): return "function"

class Token:
    def __init__(self, type, value, line, col):
        self.type = type
        self.value = value
        self.line = line
        self.col = col
    def __repr__(self): return f"{self.type}({self.value})"

class Lexer:
    def __init__(self, text, filename):
        self.text = text
        self.filename = filename
        self.pos = 0
        self.line = 1
        self.col = 0
        self.keywords = {
            'let', 'function', 'return', 'if', 'then', 'else', 'end', 'while', 'do', 'for', 'in', 'and', 'or', 'not', 'nil', 'true', 'false', 'break'
        }
    def error(self, msg):
        print(f"Error: {self.filename} (line {self.line}, column {self.col}) - {msg}")
        sys.exit(2)
    def lex(self):
        tokens = []
        while self.pos < len(self.text):
            c = self.text[self.pos]
            if c.isspace():
                if c == '\n': self.line += 1; self.col = 0
                else: self.col += 1
                self.pos += 1
            elif c == '#':
                while self.pos < len(self.text) and self.text[self.pos] != '\n': self.pos += 1
            elif c.isalpha() or c == '_':
                start = self.pos; start_col = self.col
                while self.pos < len(self.text) and (self.text[self.pos].isalnum() or self.text[self.pos] == '_'): self.pos += 1; self.col += 1
                val = self.text[start:self.pos]
                if val in self.keywords: tokens.append(Token(val.upper(), val, self.line, start_col))
                else: tokens.append(Token('ID', val, self.line, start_col))
            elif c.isdigit():
                start = self.pos; start_col = self.col
                while self.pos < len(self.text) and self.text[self.pos].isdigit(): self.pos += 1; self.col += 1
                if self.pos < len(self.text) and self.text[self.pos] == '.' and (self.pos + 1 < len(self.text) and self.text[self.pos+1].isdigit()):
                    self.pos += 1; self.col += 1
                    while self.pos < len(self.text) and self.text[self.pos].isdigit(): self.pos += 1; self.col += 1
                    tokens.append(Token('FLOAT', self.text[start:self.pos], self.line, start_col))
                else: tokens.append(Token('INT', self.text[start:self.pos], self.line, start_col))
            elif c == '"':
                start_col = self.col; self.pos += 1; self.col += 1; val = ""
                while self.pos < len(self.text) and self.text[self.pos] != '"':
                    if self.text[self.pos] == '\\':
                        self.pos += 1; self.col += 1; esc = self.text[self.pos]
                        if esc == 'n': val += '\n'
                        elif esc == 't': val += '\t'
                        elif esc == '"': val += '"'
                        elif esc == '\\': val += '\\'
                        elif esc == '0': val += '\0'
                        else: self.error(f"invalid escape sequence '\\{esc}'.")
                    else: val += self.text[self.pos]
                    self.pos += 1; self.col += 1
                self.pos += 1; self.col += 1; tokens.append(Token('STRING', val, self.line, start_col))
            elif c == '=':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '=':
                    tokens.append(Token('EQ', '==', self.line, self.col)); self.pos += 2; self.col += 2
                else: tokens.append(Token('ASSIGN', '=', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '!':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '=':
                    tokens.append(Token('NE', '!=', self.line, self.col)); self.pos += 2; self.col += 2
                else: self.error(f"unexpected '{c}'")
            elif c == '<':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '=':
                    tokens.append(Token('LE', '<=', self.line, self.col)); self.pos += 2; self.col += 2
                elif self.pos+1 < len(self.text) and self.text[self.pos+1] == '<':
                    tokens.append(Token('HEREDOC', '<<', self.line, self.col)); self.pos += 2; self.col += 2
                else: tokens.append(Token('LT', '<', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '>':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '=':
                    tokens.append(Token('GE', '>=', self.line, self.col)); self.pos += 2; self.col += 2
                elif self.pos+1 < len(self.text) and self.text[self.pos+1] == '>':
                    tokens.append(Token('APPEND', '>>', self.line, self.col)); self.pos += 2; self.col += 2
                else: tokens.append(Token('GT', '>', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '+':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '+':
                    tokens.append(Token('CONCAT', '++', self.line, self.col)); self.pos += 2; self.col += 2
                else: tokens.append(Token('PLUS', '+', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '-': tokens.append(Token('MINUS', '-', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '*': tokens.append(Token('MUL', '*', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '/': tokens.append(Token('DIV', '/', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '%': tokens.append(Token('MOD', '%', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '(': tokens.append(Token('LPAREN', '(', self.line, self.col)); self.pos += 1; self.col += 1
