        self.col = 0
        self.keywords = {
            'let', 'function', 'return', 'if', 'then', 'else', 'end', 'while', 'do', 'for', 'in', 'and', 'or', 'not', 'nil', 'true', 'false', 'break'
        }
    def error(self, msg):
        print(f"Error: {self.filename} (line {self.line}, column {self.col}) - {msg}")
        sys.exit(2)
    def lex(self):
        tokens = []
        while self.pos < len(self.text):
            c = self.text[self.pos]
            if c.isspace():
                if c == '\n': self.line += 1; self.col = 0
                else: self.col += 1
                self.pos += 1
            elif c == '#':
                while self.pos < len(self.text) and self.text[self.pos] != '\n': self.pos += 1
            elif c.isalpha() or c == '_':
                start = self.pos; start_col = self.col
                while self.pos < len(self.text) and (self.text[self.pos].isalnum() or self.text[self.pos] == '_'): self.pos += 1; self.col += 1
                val = self.text[start:self.pos]
                if val in self.keywords: tokens.append(Token(val.upper(), val, self.line, start_col))
                else: tokens.append(Token('ID', val, self.line, start_col))
            elif c.isdigit():
                start = self.pos; start_col = self.col
                while self.pos < len(self.text) and self.text[self.pos].isdigit(): self.pos += 1; self.col += 1
                if self.pos < len(self.text) and self.text[self.pos] == '.' and (self.pos + 1 < len(self.text) and self.text[self.pos+1].isdigit()):
                    self.pos += 1; self.col += 1
                    while self.pos < len(self.text) and self.text[self.pos].isdigit(): self.pos += 1; self.col += 1
                    tokens.append(Token('FLOAT', self.text[start:self.pos], self.line, start_col))
                else: tokens.append(Token('INT', self.text[start:self.pos], self.line, start_col))
            elif c == '"':
                start_col = self.col; self.pos += 1; self.col += 1; val = ""
                while self.pos < len(self.text) and self.text[self.pos] != '"':
                    if self.text[self.pos] == '\\':
                        self.pos += 1; self.col += 1; esc = self.text[self.pos]
                        if esc == 'n': val += '\n'
                        elif esc == 't': val += '\t'
                        elif esc == '"': val += '"'
                        elif esc == '\\': val += '\\'
                        elif esc == '0': val += '\0'
                        else: self.error(f"invalid escape sequence '\\{esc}'.")
                    else: val += self.text[self.pos]
                    self.pos += 1; self.col += 1
                self.pos += 1; self.col += 1; tokens.append(Token('STRING', val, self.line, start_col))
            elif c == '=':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '=':
                    tokens.append(Token('EQ', '==', self.line, self.col)); self.pos += 2; self.col += 2
                else: tokens.append(Token('ASSIGN', '=', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '!':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '=':
                    tokens.append(Token('NE', '!=', self.line, self.col)); self.pos += 2; self.col += 2
                else: self.error(f"unexpected '{c}'")
            elif c == '<':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '=':
                    tokens.append(Token('LE', '<=', self.line, self.col)); self.pos += 2; self.col += 2
                elif self.pos+1 < len(self.text) and self.text[self.pos+1] == '<':
                    tokens.append(Token('HEREDOC', '<<', self.line, self.col)); self.pos += 2; self.col += 2
                else: tokens.append(Token('LT', '<', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '>':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '=':
                    tokens.append(Token('GE', '>=', self.line, self.col)); self.pos += 2; self.col += 2
                elif self.pos+1 < len(self.text) and self.text[self.pos+1] == '>':
                    tokens.append(Token('APPEND', '>>', self.line, self.col)); self.pos += 2; self.col += 2
                else: tokens.append(Token('GT', '>', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '+':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '+':
                    tokens.append(Token('CONCAT', '++', self.line, self.col)); self.pos += 2; self.col += 2
                else: tokens.append(Token('PLUS', '+', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '-': tokens.append(Token('MINUS', '-', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '*': tokens.append(Token('MUL', '*', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '/': tokens.append(Token('DIV', '/', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '%': tokens.append(Token('MOD', '%', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '(': tokens.append(Token('LPAREN', '(', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == ')': tokens.append(Token('RPAREN', ')', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '[': tokens.append(Token('LBRACKET', '[', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == ']': tokens.append(Token('RBRACKET', ']', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '{': tokens.append(Token('LBRACE', '{', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '}': tokens.append(Token('RBRACE', '}', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '$':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '{':
                    tokens.append(Token('LCAPTURE', '${', self.line, self.col)); self.pos += 2; self.col += 2
                else:
                    start = self.pos; self.pos += 1; self.col += 1
                    while self.pos < len(self.text) and (self.text[self.pos].isalnum() or self.text[self.pos] == '_'): self.pos += 1; self.col += 1
                    tokens.append(Token('DOLLAR_ID', self.text[start:self.pos], self.line, self.col))
            elif c == '@':
                if self.pos+1 < len(self.text) and self.text[self.pos+1] == '[':
                    tokens.append(Token('LDICT', '@[', self.line, self.col)); self.pos += 2; self.col += 2
            elif c == ':': tokens.append(Token('COLON', ':', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == ',': tokens.append(Token('COMMA', ',', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '.': tokens.append(Token('DOT', '.', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == ';': tokens.append(Token('SEMI', ';', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '?': tokens.append(Token('QUESTION', '?', self.line, self.col)); self.pos += 1; self.col += 1
            elif c == '|': tokens.append(Token('PIPE', '|', self.line, self.col)); self.pos += 1; self.col += 1
            else: self.error(f"unexpected '{c}'")
        return tokens

class Parser:
    def __init__(self, tokens, filename):
        self.tokens = tokens; self.filename = filename; self.pos = 0
    def peek(self, n=0):
        if self.pos+n < len(self.tokens): return self.tokens[self.pos+n]
        return Token('EOF', '', 0, 0)
    def consume(self, type=None):
        t = self.peek()
        if type and t.type != type: self.error(f"unexpected '{t.value}', expected {type}")
        self.pos += 1; return t
    def match(self, type):
        if self.peek().type == type: self.consume(); return True
        return False
    def error(self, msg):
        t = self.peek(); print(f"Error: {self.filename} (line {t.line}, column {t.col}) - {msg}"); sys.exit(2)
    def parse_program(self):
        stmts = []
        while self.pos < len(self.tokens): stmts.append(self.parse_stmt())
        return stmts
    def parse_stmt(self):
        t = self.peek()
        if t.type == 'LET':
            self.consume(); id = self.consume('ID').value
            expr = self.parse_expr() if self.match('ASSIGN') else None
            return ('let', id, expr)
        if t.type == 'RETURN':
            self.consume(); expr = self.parse_expr() if self.peek().type not in ('END', 'ELSE', 'RBRACE', 'SEMI') else None
            return ('return', expr)
        if t.type == 'BREAK': self.consume(); return ('break',)
        if t.type == 'WHILE':
            self.consume(); cond = self.parse_expr(); self.consume('DO')
            body = []
            while self.peek().type != 'END': body.append(self.parse_stmt())
            self.consume('END'); return ('while', cond, body)
        if t.type == 'FOR':
            self.consume(); id = self.consume('ID').value; self.consume('IN'); iter_e = self.parse_expr(); self.consume('DO')
            body = []
            while self.peek().type != 'END': body.append(self.parse_stmt())
            self.consume('END'); return ('for', id, iter_e, body)
        if t.type == 'IF':
            self.consume(); cond = self.parse_expr(); self.consume('THEN'); then_b = []
            while self.peek().type not in ('ELSE', 'END'): then_b.append(self.parse_stmt())
            else_b = []
            if self.match('ELSE'):
                while self.peek().type != 'END': else_b.append(self.parse_stmt())
            self.consume('END'); return ('if', cond, then_b, else_b)
        if t.type == 'ID' and self.peek(1).type == 'ASSIGN':
            id = self.consume().value; self.consume('ASSIGN'); return ('assign', id, self.parse_expr())
        expr = self.parse_expr()
        if self.match('ASSIGN'): return ('assign_index', expr, self.parse_expr())
        return ('expr', expr)
    def parse_expr(self): return self.parse_or()
    def parse_or(self):
        l = self.parse_and()
        while self.match('OR'): l = ('binop', 'or', l, self.parse_and())
        return l
    def parse_and(self):
        l = self.parse_comp()
        while self.match('AND'): l = ('binop', 'and', l, self.parse_comp())
        return l
    def parse_comp(self):
        l = self.parse_concat()
        t = self.peek()
        if t.type in ('EQ', 'NE', 'LT', 'LE', 'GT', 'GE'):
            self.consume(); l = ('binop', t.value, l, self.parse_concat())
        return l
    def parse_concat(self):
        l = self.parse_add()
        while self.match('CONCAT'): l = ('binop', '++', l, self.parse_add())
        return l
    def parse_add(self):
        l = self.parse_mul()
        while True:
            t = self.peek()
            if t.type in ('PLUS', 'MINUS'): self.consume(); l = ('binop', t.value, l, self.parse_mul())
            else: break
        return l
    def parse_mul(self):
        l = self.parse_unary()
        while True:
            t = self.peek()
            if t.type in ('MUL', 'DIV', 'MOD'): self.consume(); l = ('binop', t.value, l, self.parse_unary())
            else: break
        return l
    def parse_unary(self):
        t = self.peek()
        if t.type in ('MINUS', 'NOT'): self.consume(); return ('unary', t.value, self.parse_unary())
        return self.parse_postfix()
    def parse_postfix(self):
        e = self.parse_primary()
        while True:
            t = self.peek()
            if t.type == 'LPAREN':
                self.consume(); args = []
                if self.peek().type != 'RPAREN':
                    args.append(self.parse_expr())
                    while self.match('COMMA'):
                        if self.peek().type == 'RPAREN': break
                        args.append(self.parse_expr())
                self.consume('RPAREN'); e = ('call', e, args)
            elif t.type == 'LBRACKET':
                self.consume(); idx = self.parse_expr(); self.consume('RBRACKET'); e = ('index', e, idx)
            elif t.type == 'DOT':
                self.consume(); id = self.consume('ID').value; e = ('index', e, ('literal', String(id)))
            elif t.type == 'QUESTION': self.consume(); e = ('try', e)
            else: break
        return e
    def parse_primary(self):
        t = self.consume()
        if t.type == 'NIL': return ('literal', Nil())
        if t.type == 'TRUE': return ('literal', Bool(True))
        if t.type == 'FALSE': return ('literal', Bool(False))
        if t.type == 'INT': return ('literal', Int(int(t.value)))
        if t.type == 'FLOAT': return ('literal', Float(float(t.value)))
        if t.type == 'STRING': return ('literal', String(t.value))
        if t.type == 'ID': return ('id', t.value)
        if t.type == 'LPAREN':
            if self.peek().type == 'IF': e = self.parse_if()
            else: e = self.parse_expr()
            self.consume('RPAREN'); return e
        if t.type == 'LBRACKET':
            els = []
            if self.peek().type != 'RBRACKET':
                els.append(self.parse_expr())
                while self.match('COMMA'):
                    if self.peek().type == 'RBRACKET': break
                    els.append(self.parse_expr())
            self.consume('RBRACKET'); return ('array', els)
        if t.type == 'LDICT':
            items = []
            while self.peek().type != 'RBRACKET':
                k = self.consume('ID').value; self.consume('COLON'); items.append((k, self.parse_expr()))
                if not self.match('COMMA'): break
            self.consume('RBRACKET'); return ('dict', items)
        if t.type == 'FUNCTION':
            self.consume('LPAREN'); params = []
            if self.peek().type != 'RPAREN':
                params.append(self.consume('ID').value)
                while self.match('COMMA'):
                    if self.peek().type == 'RPAREN': break
                    params.append(self.consume('ID').value)
            self.consume('RPAREN'); body = []
            while self.peek().type != 'END': body.append(self.parse_stmt())
            self.consume('END'); return ('function', params, body)
        if t.type == 'LBRACE': return self.parse_cmd_block('{')
        if t.type == 'LCAPTURE': return self.parse_cmd_block('${')
        return ('literal', Nil())
    def parse_cmd_block(self, type_str):
        cmds = []
        while self.peek().type != 'RBRACE':
            cmds.append(self.parse_command())
            if self.match('SEMI'): continue
        self.consume('RBRACE'); return ('cmd_block', type_str, cmds)
    def parse_command(self):
        parts = []
        while self.peek().type not in ('RBRACE', 'SEMI', 'PIPE', 'QUESTION'):
            t = self.peek()
            if t.type in ('GT', 'APPEND', 'HEREDOC'):
                op = self.consume().value; parts.append(('redir', op, self.parse_cmd_arg()))
            else: parts.append(('arg', self.parse_cmd_arg()))
        if self.match('PIPE'): return ('pipe', parts, self.parse_command())
        return ('command', parts)
    def parse_cmd_arg(self):
        t = self.consume()
        if t.type == 'DOLLAR_ID': return ('dollar_id', t.value[1:])
        return ('literal_arg', t.value)

class Environment:
    def __init__(self, parent=None):
        self.vars = {}; self.parent = parent
    def get(self, name):
        if name in self.vars: return self.vars[name]
        return self.parent.get(name) if self.parent else None
    def set(self, name, val): self.vars[name] = val
    def update(self, name, val):
        if name in self.vars: self.vars[name] = val; return True
        return self.parent.update(name, val) if self.parent else False

class Interpreter:
    def __init__(self, filename):
        self.filename = filename; self.global_env = Environment(); self.init_std()
    def init_std(self):
        std = Dict()
        std.val[String("print")] = NativeFunction(self.std_print)
        std.val[String("println")] = NativeFunction(self.std_println)
        std.val[String("type")] = NativeFunction(self.std_type)
        std.val[String("len")] = NativeFunction(self.std_len)
        std.val[String("iter")] = NativeFunction(self.std_iter)
        std.val[String("range")] = NativeFunction(self.std_range)
        std.val[String("import")] = NativeFunction(self.std_import)
        std.val[String("has_error")] = NativeFunction(self.std_has_error)
        std.val[String("error")] = NativeFunction(self.std_error)
        std.val[String("catch")] = NativeFunction(self.std_catch)
        std.val[String("to_string")] = NativeFunction(self.std_to_string)
        self.global_env.set("std", std)
    def std_print(self, args, pos=None):
        for a in args: sys.stdout.write(a.val if isinstance(a, String) else repr(a))
        return Nil()
    def std_println(self, args, pos=None):
        self.std_print(args, pos); sys.stdout.write("\n"); return Nil()
    def std_type(self, args, pos=None):
        v = args[0]
        if isinstance(v, Nil): return String("nil")
        if isinstance(v, Bool): return String("bool")
        if isinstance(v, Int): return String("int")
        if isinstance(v, Float): return String("float")
        if isinstance(v, Char): return String("char")
        if isinstance(v, String): return String("string")
        if isinstance(v, Array): return String("array")
        if isinstance(v, Dict): return String("dict")
        if isinstance(v, Error): return String("error")
        return String("function")
    def std_len(self, args, pos=None):
        v = args[0]
        if isinstance(v, (Array, String, Dict)): return Int(len(v.val))
        return Int(0)
    def std_iter(self, args, pos=None):
        v = args[0]
        if isinstance(v, Array):
            idx = 0
            def nxt(a, p=None):
                nonlocal idx
                if idx >= len(v.val): return Dict({String("finished"): Bool(True)})
                val = v.val[idx]; idx += 1; return Dict({String("finished"): Bool(False), String("value"): val})
            return NativeFunction(nxt)
        if isinstance(v, Dict):
            items = list(v.val.items()); idx = 0
            def nxt(a, p=None):
                nonlocal idx
                if idx >= len(items): return Dict({String("finished"): Bool(True)})
                k, val = items[idx]; idx += 1; return Dict({String("finished"): Bool(False), String("key"): k, String("value"): val})
            return NativeFunction(nxt)
        return Nil()
    def std_range(self, args, pos=None):
        s, e, st = args[0].val, args[1].val, args[2].val; idx = s
        def nxt(a, p=None):
            nonlocal idx
            if (st > 0 and idx >= e) or (st < 0 and idx <= e): return Dict({String("finished"): Bool(True)})
            v = idx; idx += st; return Dict({String("finished"): Bool(False), String("value"): Int(v)})
        return NativeFunction(nxt)
    def std_import(self, args, pos=None):
        path = args[0].val
        with open(path, 'r') as f: text = f.read()
        interp = Interpreter(path)
        tokens = Lexer(text, path).lex()
        stmts = Parser(tokens, path).parse_program()
        val = Nil()
        for s in stmts: val = interp.eval_stmt(s, interp.global_env)
        return val
    def std_has_error(self, args, pos=None): return Bool(isinstance(args[0], Error))
    def std_error(self, args, pos=None): return Error(args[0].val, args[1])
    def std_catch(self, args, pos=None):
        try: return self.call(args[0], [])
        except HushPanic as p: return Error(f"caught panic: {p.message}", String("panic"))
    def std_to_string(self, args, pos=None): return String(repr(args[0]))
    def panic(self, msg, pos=None): raise HushPanic(msg, pos)
    def eval_stmt(self, stmt, env):
        t = stmt[0]
        if t == 'let': val = self.eval_expr(stmt[2], env) if stmt[2] else Nil(); env.set(stmt[1], val); return val
        elif t == 'assign': val = self.eval_expr(stmt[2], env); env.update(stmt[1], val); return val
        elif t == 'return': raise ReturnException(self.eval_expr(stmt[1], env) if stmt[1] else Nil())
        elif t == 'break': raise BreakException()
        elif t == 'while':
            while self.eval_expr(stmt[1], env).val:
                try:
                    for s in stmt[2]: self.eval_stmt(s, env)
                except BreakException: break
            return Nil()
        elif t == 'for':
            it = self.eval_expr(stmt[2], env)
            while True:
                res = self.call(it, [])
                if res.val[String("finished")].val: break
                sub = Environment(env); sub.set(stmt[1], res.val[String("value")])
                try:
                    for s in stmt[3]: self.eval_stmt(s, sub)
                except BreakException: break
            return Nil()
        elif t == 'if':
            if self.eval_expr(stmt[1], env).val:
                v = Nil()
                for s in stmt[2]: v = self.eval_stmt(s, env)
                return v
            else:
                v = Nil()
                for s in stmt[3]: v = self.eval_stmt(s, env)
                return v
        elif t == 'expr': return self.eval_expr(stmt[1], env)
        return Nil()
    def eval_expr(self, e, env):
        t = e[0]
        if t == 'literal': return e[1]
        if t == 'id':
            v = env.get(e[1])
            if v is None: self.panic(f"undeclared variable '{e[1]}'")
            return v
        if t == 'binop':
            l, r = self.eval_expr(e[2], env), self.eval_expr(e[3], env); op = e[1]
            if op == '+': return Int(l.val + r.val)
            if op == '-': return Int(l.val - r.val)
            if op == '*': return Int(l.val * r.val)
            if op == '/': return Int(l.val // r.val)
            if op == '++': return String(l.val + r.val)
            if op == '==': return Bool(l == r)
            if op == '!=': return Bool(not (l == r))
            if op == '<': return Bool(l.val < r.val)
            if op == '>': return Bool(l.val > r.val)
            if op == '<=': return Bool(l.val <= r.val)
            if op == '>=': return Bool(l.val >= r.val)
            if op == 'and': return Bool(l.val and r.val)
            if op == 'or': return Bool(l.val or r.val)
        if t == 'unary':
            r = self.eval_expr(e[2], env); op = e[1]
            if op == '-': return Int(-r.val)
            if op == 'not': return Bool(not r.val)
        if t == 'call':
            if e[1][0] == 'index':
                obj = self.eval_expr(e[1][1], env); idx = self.eval_expr(e[1][2], env)
                func = self.get_index(obj, idx); args = [self.eval_expr(x, env) for x in e[2]]
                return self.call(func, args, obj=obj)
            else:
                func = self.eval_expr(e[1], env); args = [self.eval_expr(x, env) for x in e[2]]
                return self.call(func, args)
        if t == 'index': return self.get_index(self.eval_expr(e[1], env), self.eval_expr(e[2], env))
        if t == 'function': return Function(None, e[1], e[2], env)
        if t == 'array': return Array([self.eval_expr(x, env) for x in e[1]])
        if t == 'dict':
            d = Dict()
            for k, v in e[1]: d.val[String(k)] = self.eval_expr(v, env)
            return d
        if t == 'cmd_block':
            cap = e[1] == '${'
            res = subprocess.run([p[1][1] for p in e[2][0][1]], capture_output=cap)
            if cap: return Dict({String("stdout"): String(res.stdout.decode()), String("stderr"): String(res.stderr.decode())})
            return Nil()
        if t == 'try':
            v = self.eval_expr(e[1], env)
            if isinstance(v, Error): raise ReturnException(v)
            return v
        return Nil()
    def get_index(self, o, i):
        if isinstance(o, Array): return o.val[i.val]
        if isinstance(o, Dict): return o.val[i]
        if isinstance(o, String): return Char(o.val[i.val])
        return Nil()
    def call(self, f, args, obj=None):
        if isinstance(f, NativeFunction): return f.fn(args)
        if isinstance(f, Function):
            sub = Environment(f.env)
            if obj: sub.set("self", obj)
            for i, p in enumerate(f.params): sub.set(p, args[i] if i < len(args) else Nil())
            try:
                v = Nil()
                for s in f.body: v = self.eval_stmt(s, sub)
                return v
