    def __eq__(self, other): return isinstance(other, String) and self.val == other.val
    def __hash__(self): return hash(self.val)

class Array(Value):
    def __init__(self, val): self.val = val
    def __repr__(self):
        return "[ " + ", ".join(repr(v) for v in self.val) + " ]" if self.val else "[]"
    def __eq__(self, other): return self is other

class Dict(Value):
    def __init__(self, val=None):
        self.val = val or {} # Value -> Value
    def __repr__(self):
        if not self.val: return "@[]"
        items = []
        for k, v in self.val.items():
            k_repr = f'"{k.val}"' if isinstance(k, String) else repr(k)
            items.append((k_repr, repr(v)))
